from __future__ import annotations

from dataclasses import dataclass, replace
from decimal import Decimal, InvalidOperation
from typing import Protocol, TypeAlias


MoneyInput: TypeAlias = Decimal | int | float | str

_ZERO_AMOUNT = Decimal("0")
_ONE_HUNDRED = Decimal("100")


class ShoppingCartError(Exception):
    """Base exception for shopping-cart operations."""


class InvalidProductNameError(ShoppingCartError):
    """Raised when a product name is empty or invalid."""


class InvalidUnitPriceError(ShoppingCartError):
    """Raised when a unit price is invalid or negative."""


class InvalidQuantityError(ShoppingCartError):
    """Raised when an item quantity is not a positive integer."""


class DuplicateCartItemError(ShoppingCartError):
    """Raised when an item with the same product name already exists."""


class CartItemNotFoundError(ShoppingCartError):
    """Raised when a requested cart item does not exist."""


class InvalidPercentageDiscountError(ShoppingCartError):
    """Raised when a percentage discount is outside the valid range."""


class InvalidFlatDiscountError(ShoppingCartError):
    """Raised when a flat discount is invalid or negative."""


def _normalize_product_name(product_name: str) -> str:
    if not isinstance(product_name, str):
        raise InvalidProductNameError("Product name must be a string.")

    normalized_name = product_name.strip()
    if not normalized_name:
        raise InvalidProductNameError("Product name cannot be empty or whitespace.")

    return normalized_name


def _validate_quantity(quantity: int) -> int:
    if isinstance(quantity, bool) or not isinstance(quantity, int):
        raise InvalidQuantityError("Quantity must be an integer.")

    if quantity <= 0:
        raise InvalidQuantityError("Quantity must be greater than zero.")

    return quantity


def _convert_non_negative_decimal(
    value: MoneyInput,
    *,
    field_name: str,
    exception_type: type[ShoppingCartError],
) -> Decimal:
    if isinstance(value, bool) or not isinstance(value, (Decimal, int, float, str)):
        raise exception_type(
            f"{field_name} must be a Decimal, integer, float, or numeric string."
        )

    try:
        decimal_value = value if isinstance(value, Decimal) else Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError) as conversion_error:
        raise exception_type(
            f"{field_name} must be a valid numeric value; received {value!r}."
        ) from conversion_error

    if not decimal_value.is_finite():
        raise exception_type(f"{field_name} must be finite.")

    if decimal_value < _ZERO_AMOUNT:
        raise exception_type(f"{field_name} cannot be negative.")

    return decimal_value


@dataclass(frozen=True, slots=True, init=False)
class CartItem:
    """An immutable, validated product entry in a shopping cart."""

    product_name: str
    unit_price: Decimal
    quantity: int

    def __init__(
        self,
        product_name: str,
        unit_price: MoneyInput,
        quantity: int,
    ) -> None:
        """Create a cart item from validated and normalized values."""
        object.__setattr__(
            self,
            "product_name",
            _normalize_product_name(product_name),
        )
        object.__setattr__(
            self,
            "unit_price",
            _convert_non_negative_decimal(
                unit_price,
                field_name="Unit price",
                exception_type=InvalidUnitPriceError,
            ),
        )
        object.__setattr__(self, "quantity", _validate_quantity(quantity))

    @property
    def line_total(self) -> Decimal:
        """Return the item's unit price multiplied by its quantity."""
        return self.unit_price * self.quantity


class _Discount(Protocol):
    def amount_for(self, subtotal: Decimal) -> Decimal:
        """Return the discount amount applicable to a subtotal."""


@dataclass(frozen=True, slots=True)
class _PercentageDiscount:
    percentage: Decimal

    def amount_for(self, subtotal: Decimal) -> Decimal:
        """Calculate the percentage-based discount amount."""
        return subtotal * self.percentage / _ONE_HUNDRED


@dataclass(frozen=True, slots=True)
class _FlatDiscount:
    amount: Decimal

    def amount_for(self, subtotal: Decimal) -> Decimal:
        """Calculate the flat discount without producing a negative total."""
        return min(self.amount, subtotal)


class ShoppingCart:
    """Manage cart items and one optional discount.

    Product names are stripped of surrounding whitespace and treated as
    case-sensitive identifiers. Applying a new discount replaces the currently
    active discount.
    """

    def __init__(self) -> None:
        """Initialize an empty shopping cart without an active discount."""
        self._items: dict[str, CartItem] = {}
        self._discount: _Discount | None = None

    def add_item(
        self,
        product_name: str,
        unit_price: MoneyInput,
        quantity: int,
    ) -> CartItem:
        """Add a new item and return the created cart item.

        Raises:
            InvalidProductNameError: If the product name is invalid.
            InvalidUnitPriceError: If the price is invalid or negative.
            InvalidQuantityError: If the quantity is not a positive integer.
            DuplicateCartItemError: If the product is already in the cart.
        """
        new_item = CartItem(product_name, unit_price, quantity)

        if new_item.product_name in self._items:
            raise DuplicateCartItemError(
                f"Product {new_item.product_name!r} is already in the cart; "
                "use update_quantity() to change its quantity."
            )

        self._items[new_item.product_name] = new_item
        return new_item

    def remove_item(self, product_name: str) -> CartItem:
        """Remove an item by product name and return the removed item.

        Raises:
            InvalidProductNameError: If the product name is invalid.
            CartItemNotFoundError: If the product is not in the cart.
        """
        item_key = self._require_item_key(product_name)
        return self._items.pop(item_key)

    def update_quantity(
        self,
        product_name: str,
        quantity: int,
    ) -> CartItem:
        """Update an existing item's quantity and return the updated item.

        Raises:
            InvalidProductNameError: If the product name is invalid.
            InvalidQuantityError: If the quantity is not a positive integer.
            CartItemNotFoundError: If the product is not in the cart.
        """
        item_key = self._require_item_key(product_name)
        updated_item = replace(self._items[item_key], quantity=quantity)
        self._items[item_key] = updated_item
        return updated_item

    def calculate_subtotal(self) -> Decimal:
        """Return the total price of all items before discounts."""
        return sum(
            (cart_item.line_total for cart_item in self._items.values()),
            start=_ZERO_AMOUNT,
        )

    def apply_percentage_discount(self, percentage: MoneyInput) -> None:
        """Replace the active discount with a percentage discount.

        The percentage must be between zero and one hundred, inclusive.

        Raises:
            InvalidPercentageDiscountError: If the percentage is invalid.
        """
        normalized_percentage = _convert_non_negative_decimal(
            percentage,
            field_name="Percentage discount",
            exception_type=InvalidPercentageDiscountError,
        )

        if normalized_percentage > _ONE_HUNDRED:
            raise InvalidPercentageDiscountError(
                "Percentage discount cannot exceed 100."
            )

        self._discount = _PercentageDiscount(normalized_percentage)

    def apply_flat_discount(self, amount: MoneyInput) -> None:
        """Replace the active discount with a flat discount.

        A flat discount larger than the subtotal reduces the total to zero.

        Raises:
            InvalidFlatDiscountError: If the amount is invalid or negative.
        """
        normalized_amount = _convert_non_negative_decimal(
            amount,
            field_name="Flat discount",
            exception_type=InvalidFlatDiscountError,
        )
        self._discount = _FlatDiscount(normalized_amount)

    def clear_discount(self) -> None:
        """Remove the currently active discount."""
        self._discount = None

    def calculate_discount(self) -> Decimal:
        """Return the discount amount applicable to the current subtotal."""
        subtotal = self.calculate_subtotal()
        return self._calculate_discount_for(subtotal)

    def calculate_total(self) -> Decimal:
        """Return the cart total after applying the active discount."""
        subtotal = self.calculate_subtotal()
        return subtotal - self._calculate_discount_for(subtotal)

    def list_items(self) -> list[CartItem]:
        """Return a snapshot of all items in insertion order."""
        return list(self._items.values())

    def clear(self) -> None:
        """Remove all items and the active discount from the cart."""
        self._items.clear()
        self.clear_discount()

    def _require_item_key(self, product_name: str) -> str:
        normalized_name = _normalize_product_name(product_name)

        if normalized_name not in self._items:
            raise CartItemNotFoundError(
                f"Product {normalized_name!r} is not in the cart."
            )

        return normalized_name

    def _calculate_discount_for(self, subtotal: Decimal) -> Decimal:
        if self._discount is None:
            return _ZERO_AMOUNT

        return self._discount.amount_for(subtotal)
